    show([1, 2, 4, 7, 12])

from typing import Tuple

def join_data(left_orbits: int, right_orbits: int) -> Tuple[int, int, int]:
    if left_orbits <= 0 or right_orbits <= 0:
        raise ValueError("orbit counts must be positive")
    left_c, right_c = left_orbits - 1, right_orbits - 1
    joined_c = left_c + right_c + 1
    assert joined_c == left_orbits + right_orbits - 1
    return left_c, right_c, joined_c

if __name__ == "__main__":
    for pair in [(1, 1), (2, 3), (4, 7)]:
        print(pair, join_data(*pair))

