from typing import Dict, Hashable, Mapping, Tuple

def form_join(left: Mapping[Hashable, Hashable], right: Mapping[Hashable, Hashable]) -> Dict[Tuple[str, Hashable], Tuple[str, Hashable]]:
    joined: Dict[Tuple[str, Hashable], Tuple[str, Hashable]] = {}
    for v, a in left.items():
        joined[("L", v)] = ("L", a)
    for v, a in right.items():
        joined[("R", v)] = ("R", a)
    return joined

def joined_coindex(left_coindex: int, right_coindex: int) -> int:
    if left_coindex < 0 or right_coindex < 0:
        raise ValueError("coindices must be nonnegative")
    return left_coindex + right_coindex + 1

from typing import Hashable, Mapping

def validate_map(source_anti: Mapping[Hashable, Hashable], target_anti: Mapping[Hashable, Hashable], mapping: Mapping[Hashable, Hashable]) -> bool:
    if set(mapping) != set(source_anti):
        return False
    images = list(mapping.values())
    if any(x not in target_anti for x in images) or len(images) != len(set(images)):
        return False
    return all(mapping[source_anti[v]] == target_anti[mapping[v]] for v in source_anti)

